@page "/dispatch"
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject ShipmentTracker.Client.Services.IShipmentService ShipmentService

<PageTitle>Dispatch Dashboard</PageTitle>

<h1>Dispatch Dashboard</h1>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by destination..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments match your filter.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>ETA</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td><code>@s.TrackingNumber</code></td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                    <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    <td>
                        @if (s.Status != ShipmentTracker.Client.Models.ShipmentStatus.Delivered)
                        {
                            <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                    @onchange="(e) => UpdateStatus(s.Id, e)">
                                <option value="">Change status...</option>
                                @foreach (var status in Enum.GetValues<ShipmentTracker.Client.Models.ShipmentStatus>())
                                {
                                    @if (status != s.Status)
                                    {
                                        <option value="@((int)status)">@status</option>
                                    }
                                }
                            </select>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentTracker.Client.Models.Shipment>? shipments;
    private string filterText = string.Empty;

    private IEnumerable<ShipmentTracker.Client.Models.Shipment> FilteredShipments =>
        shipments?.Where(s => string.IsNullOrEmpty(filterText)
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
            || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (e.Value is string val && int.TryParse(val, out var statusInt))
        {
            var status = (ShipmentTracker.Client.Models.ShipmentStatus)statusInt;
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
    }

    private static string GetStatusBadgeClass(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
    {
        ShipmentTracker.Client.Models.ShipmentStatus.Delivered => "bg-success",
        ShipmentTracker.Client.Models.ShipmentStatus.InTransit => "bg-primary",
        ShipmentTracker.Client.Models.ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentTracker.Client.Models.ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentTracker.Client.Models.ShipmentStatus.Pending => "bg-secondary",
        ShipmentTracker.Client.Models.ShipmentStatus.PickedUp => "bg-dark",
        _ => "bg-secondary"
    };
}

